local digest = string.rep("a", 64)
local function ref(kind, value) return { kind = kind, ref = value } end
local function make_case(status, classification)
  local assertions = {}
  if status == "passed" or status == "failed" then assertions = {{ schema=results.schemas.assertion_result, assertion_id="assert-1", type="document-ready", required=true, status=status, classification=(status == "failed" and "assertion_failure" or "deterministic"), observation_ids={"obs-1"}, evidence_refs={} }} end
  return { schema=results.schemas.case_result, case_id="case-1", repository={id="repo", source_ref=ref("git", "repo@commit"), source_sha256=digest}, reviewed_case_id="reviewed-case-1", plan_ref=ref("plan", "plans/1"), plan_sha256=digest, execution_mode="cli", execution_status=status, classification=classification or (status == "failed" and "assertion_failure" or "deterministic"), observations={{schema=results.schemas.observation, observation_id="obs-1", kind="normalized-fact", subject="document", value="ready", source_ref=ref("runner", "observations/1"), evidence_refs={}}}, assertions=assertions, evidence_refs={}, timing={started_at="2026-08-13T00:00:00Z", completed_at="2026-08-13T00:00:01Z", duration_ms=1000}, non_execution_reason=(status == "lost" and "runner-disconnected" or status == "blocked" and "precondition-unavailable" or nil), trace_id="trace-1", dedup_key="dedup-1" }
end
return {
  test_validates_cli_http_browser = function() for _, mode in ipairs({"cli", "http", "browser"}) do local value=make_case("passed"); value.execution_mode=mode; t.eq(results.validate_case_result(value), value) end end,
  test_accepts_all_execution_outcomes = function() for _, status in ipairs({"failed", "skipped", "error", "blocked", "lost"}) do local value=make_case(status, status == "failed" and "assertion_failure" or (status == "error" and "execution_error" or status)); if status == "error" then value.error={code="provider-timeout",message="execution ended before assertions completed"} end; t.eq(results.validate_case_result(value), value) end end,
  test_validates_set_and_deterministic_bytes = function() local value={schema=results.schemas.case_result_set,set_id="set-1",plan_ref=ref("plan","plans/1"),plan_sha256=digest,cases={make_case("passed")},trace_id="trace-set",dedup_key="dedup-set"}; t.eq(results.canonicalize(value), results.canonicalize(value)); t.eq(results.sha256(value,function() return digest end),digest) end,
  test_rejects_unknown_fields_bad_digest_duplicates_and_foreign_plan = function() local value=make_case("passed"); value.extra=true; t.raises(function() results.validate_case_result(value) end); value=make_case("passed"); value.plan_sha256="bad"; t.raises(function() results.validate_case_result(value) end); local set={schema=results.schemas.case_result_set,set_id="set",plan_ref=ref("plan","plans/1"),plan_sha256=digest,cases={make_case("passed"),make_case("passed")},trace_id="trace",dedup_key="dedup"}; t.raises(function() results.validate_case_result_set(set) end); set.cases={make_case("passed")}; set.cases[1].plan_ref=ref("plan","foreign"); t.raises(function() results.validate_case_result_set(set) end) end,
  test_rejects_contradictions_and_unsupported_major = function() local value=make_case("passed"); value.assertions[1].status="failed"; t.raises(function() results.validate_case_result(value) end); value=make_case("lost","lost"); t.eq(results.validate_case_result(value),value); value.assertions={{ schema=results.schemas.assertion_result, assertion_id="assert-optional", type="document-ready", required=false, status="failed", classification="assertion_failure", observation_ids={"obs-1"}, evidence_refs={} }}; t.raises(function() results.validate_case_result(value) end); t.raises(function() results.negotiate("testing-case-result.v9",{[2]=true}) end); t.eq(results.negotiate(results.schemas.case_result,{[2]=true}),2) end,
}
